#!/usr/bin/env node
// OZ Browser — Bundle content preloads via webpack (v1.4.4).
//
// Cómo correr:
//   node scripts/bundle-preloads.js
//   npm run bundle:preloads
//
// Background: los preloads sandboxed de Electron 42 fallan silenciosamente
// cuando hacen `require()` de archivos siblings (smoke visual 2026-05-15
// reveló esto). Afecta a preload-content.js (auto-fill + auto-save + TOTP)
// y preload-fingerprint.js (FP UA override + canvas/audio/webgl spoofs).
//
// Fix: bundlear cada preload + sus deps relativos en un solo .js standalone
// via webpack. El bundle resuelve los requires en build-time, así el archivo
// final SOLO require `electron` (whitelisted en sandbox). Identity-manager
// y fingerprint-preload-setup cargan el bundled version en lugar del source.
//
// Output: `browser/.bundled/<name>.bundled.js`. Gitignored.
//
// Performance: ~1-2s para los 2 preloads. Corre en prestart + prepackage.

const path = require('path')
const fs = require('fs')
const webpack = require('webpack')

const REPO_ROOT = path.resolve(__dirname, '..')
const OUT_DIR = path.join(REPO_ROOT, 'browser', '.bundled')

// Each entry: { entry: source path, name: output basename (without .js) }.
const PRELOADS = [
  { entry: './browser/preload-content.js', name: 'preload-content' },
  { entry: './browser/preload-fingerprint.js', name: 'preload-fingerprint' },
]

const config = {
  mode: process.env.NODE_ENV === 'production' ? 'production' : 'development',
  // 'node' target keeps `require('electron')` external and uses CommonJS
  // module format that Electron's preload runtime understands.
  target: 'node',
  context: REPO_ROOT,
  entry: PRELOADS.reduce((acc, p) => {
    acc[p.name] = p.entry
    return acc
  }, {}),
  output: {
    path: OUT_DIR,
    filename: '[name].bundled.js',
    libraryTarget: 'commonjs2',
    // Avoid emitting __webpack_require__ runtime helpers that don't work
    // inside sandboxed preloads. Inline everything.
    iife: true,
  },
  externals: {
    // electron is the ONLY require allowed inside sandboxed preloads.
    // Everything else gets bundled.
    electron: 'commonjs2 electron',
  },
  resolve: {
    extensions: ['.js'],
  },
  optimization: {
    // No splitting — each preload must be a single self-contained file.
    splitChunks: false,
    runtimeChunk: false,
    // Minimize off in dev mode for easier debugging.
    minimize: process.env.NODE_ENV === 'production',
  },
  // Suppress webpack performance warnings — preloads are inherently small.
  performance: { hints: false },
  // No devtool source maps in the bundle — Electron's preload runtime
  // doesn't honor them and they bloat the .app.
  devtool: false,
  stats: 'errors-only',
}

// Ensure output dir exists.
fs.mkdirSync(OUT_DIR, { recursive: true })

webpack(config, (err, stats) => {
  if (err) {
    console.error('[bundle-preloads] webpack invocation failed:')
    console.error(err.stack || err)
    process.exit(1)
  }
  if (stats.hasErrors()) {
    console.error('[bundle-preloads] webpack compile errors:')
    console.error(stats.toString({ colors: true }))
    process.exit(1)
  }
  // Stamp each bundle with a generation header so devs reading the file
  // know it's auto-generated.
  for (const p of PRELOADS) {
    const file = path.join(OUT_DIR, `${p.name}.bundled.js`)
    if (!fs.existsSync(file)) {
      console.error(`[bundle-preloads] expected output missing: ${file}`)
      process.exit(1)
    }
    const content = fs.readFileSync(file, 'utf-8')
    const banner =
      `// AUTO-GENERATED by scripts/bundle-preloads.js — DO NOT EDIT.\n` +
      `// Source: ${p.entry} (+ inlined siblings via webpack).\n` +
      `// Re-bundle: npm run bundle:preloads\n\n`
    if (!content.startsWith('// AUTO-GENERATED')) {
      fs.writeFileSync(file, banner + content)
    }
  }
  console.log(
    `[bundle-preloads] bundled ${PRELOADS.length} preload(s) → ${path.relative(REPO_ROOT, OUT_DIR)}/`,
  )
  for (const p of PRELOADS) {
    const file = path.join(OUT_DIR, `${p.name}.bundled.js`)
    const size = fs.statSync(file).size
    console.log(`  ${p.name}.bundled.js  ${(size / 1024).toFixed(1)} KiB`)
  }
})
